return-response.set-body:
@{
        var id = context.Request.MatchedParameters.ContainsKey("deploymentId")
          ? context.Request.MatchedParameters["deploymentId"]
          : "default";

        // Deliberately a superset of the two documented discovery shapes. An
        // ApiManagement connection parses this according to its
        // deploymentProvider setting, and the two supported values disagree:
        //
        //   AzureOpenAI (the default)  ARM-style, name + properties.model
        //   OpenAI                     flat, id doubles as the model name
        //
        // Returning only the flat shape against the default provider fails with
        // "Failed to parse deployment response ... from provider 'AzureOpenAI'".
        // Emitting both satisfies either reader at no cost.
        return new JObject(
          new JProperty("id", id),
          new JProperty("name", id),
          new JProperty("type", "Microsoft.CognitiveServices/accounts/deployments"),
          new JProperty("object", "deployment"),
          new JProperty("model", id),
          new JProperty("owner", "organization-owner"),
          new JProperty("status", "succeeded"),
          new JProperty("scale_settings", new JObject(
            new JProperty("scale_type", "standard")
          )),
          new JProperty("sku", new JObject(
            new JProperty("name", "Standard"),
            new JProperty("capacity", 1)
          )),
          new JProperty("properties", new JObject(
            new JProperty("model", new JObject(
              new JProperty("format", "OpenAI"),
              new JProperty("name", id),
              new JProperty("version", "1")
            )),
            new JProperty("provisioningState", "Succeeded"),
            new JProperty("capabilities", new JObject(
              new JProperty("chatCompletion", "true")
            ))
          ))
        ).ToString();
      }
